1	package com.example.starter.service;
2	
3	import java.math.BigDecimal;
4	import java.math.RoundingMode;
5	import java.sql.PreparedStatement;
6	import java.sql.Statement;
7	import java.sql.Timestamp;
8	import java.time.Clock;
9	import java.time.Instant;
10	import java.util.ArrayList;
11	import java.util.LinkedHashMap;
12	import java.util.LinkedHashSet;
13	import java.util.List;
14	import java.util.Map;
15	import java.util.Set;
16	
17	import org.springframework.dao.DuplicateKeyException;
18	import org.springframework.http.HttpStatus;
19	import org.springframework.jdbc.core.JdbcTemplate;
20	import org.springframework.jdbc.support.GeneratedKeyHolder;
21	import org.springframework.stereotype.Service;
22	import org.springframework.transaction.annotation.Transactional;
23	
24	import com.example.starter.api.dto.ColorCheckRequest;
25	import com.example.starter.api.dto.CreateRecipeRequest;
26	import com.example.starter.api.dto.FeedRequest;
27	import com.example.starter.api.dto.JudgeRequest;
28	import com.example.starter.api.dto.LateColorRequest;
29	import com.example.starter.api.dto.MergeLotsRequest;
30	import com.example.starter.api.dto.RecipeItemInput;
31	import com.example.starter.api.dto.ScheduleControlledRequest;
32	import com.example.starter.api.dto.ScheduleLotRequest;
33	import com.example.starter.api.dto.WeighingInput;
34	import com.example.starter.domain.CompensationStatus;
35	import com.example.starter.domain.LotStatus;
36	import com.example.starter.domain.RecipeStatus;
37	import com.example.starter.domain.Verdict;
38	import com.example.starter.support.ApiException;
39	
40	/**
41	 * 印染配方放大与缸差控制核心服务。
42	 * 阈值：对色 ΔE&lt;=0.8 放行；称量偏差绝对值&lt;=0.5% 合法；缸差&gt;0.5 须回修且仅一次。
43	 */
44	@Service
45	public class DyeService {
46	
47	    /** 对色放行阈值（含边界，恰 0.8 合格）。 */
48	    static final BigDecimal COLOR_LIMIT = new BigDecimal("0.8");
49	    /** 称量偏差允许上限百分比（含边界，恰 0.5% 合法）。 */
50	    static final BigDecimal WEIGH_LIMIT_PCT = new BigDecimal("0.5");
51	    /** 缸差阈值：超过 0.5 须回修。 */
52	    static final BigDecimal LOT_DIFF_LIMIT = new BigDecimal("0.5");
53	    private static final int DEVIATION_SCALE = 6;
54	
55	    private final JdbcTemplate jdbc;
56	    private final IdempotencyService idempotency;
57	    private final Clock clock;
58	
59	    public DyeService(JdbcTemplate jdbc, IdempotencyService idempotency, Clock clock) {
60	        this.jdbc = jdbc;
61	        this.idempotency = idempotency;
62	        this.clock = clock;
63	    }
64	
65	    private Timestamp nowTs() {
66	        return Timestamp.from(Instant.now(clock));
67	    }
68	
69	    // ---------------------------------------------------------------------
70	    // 配方：草稿 → 发布冻结；修改已发布配方生成新版本并保留旧版本
71	    // ---------------------------------------------------------------------
72	
73	    @Transactional
74	    public ServiceResult createRecipe(CreateRecipeRequest req) {
75	        Integer exists = jdbc.query("SELECT 1 FROM recipe WHERE recipe_code = ?",
76	                rs -> rs.next() ? 1 : null, req.recipeCode());
77	        if (exists != null) {
78	            throw new ApiException(HttpStatus.CONFLICT,
79	                    "配方编码 " + req.recipeCode() + " 已存在；修改已发布配方须生成新版本");
80	        }
81	        validateItems(req.items());
82	        Timestamp now = nowTs();
83	        jdbc.update("INSERT INTO recipe (recipe_code, version, liquor_ratio, status, created_at) "
84	                + "VALUES (?, 1, ?, ?, ?)",
85	                req.recipeCode(), req.liquorRatio(), RecipeStatus.DRAFT.name(), now);
86	        Long recipeId = jdbc.queryForObject(
87	                "SELECT id FROM recipe WHERE recipe_code = ? AND version = 1", Long.class, req.recipeCode());
88	        insertItems(recipeId, req.items());
89	        return ServiceResult.created(recipeView(req.recipeCode(), 1));
90	    }
91	
92	    @Transactional
93	    public ServiceResult publishRecipe(String recipeCode) {
94	        Map<String, Object> latest = latestRecipe(recipeCode);
95	        if (RecipeStatus.PUBLISHED.name().equals(latest.get("status"))) {
96	            throw new ApiException(HttpStatus.CONFLICT,
97	                    "配方 " + recipeCode + " v" + latest.get("version") + " 已发布冻结，不能重复发布或修改");
98	        }
99	        jdbc.update("UPDATE recipe SET status = ? WHERE id = ?",
100	                RecipeStatus.PUBLISHED.name(), latest.get("id"));
101	        return ServiceResult.ok(recipeView(recipeCode, (Integer) latest.get("version")));
102	    }
103	
104	    /**
105	     * 修改已发布配方：复制为下一草稿版本，旧版本原样保留。
106	     */
107	    @Transactional
108	    public ServiceResult reviseRecipe(String recipeCode, CreateRecipeRequest req) {
109	        Map<String, Object> latest = latestRecipe(recipeCode);
110	        if (!RecipeStatus.PUBLISHED.name().equals(latest.get("status"))) {
111	            throw new ApiException(HttpStatus.CONFLICT,
112	                    "仅已发布冻结版本才能通过修订生成新版本；当前 v" + latest.get("version") + " 为草稿");
113	        }
114	        validateItems(req.items());
115	        int newVersion = (Integer) latest.get("version") + 1;
116	        Timestamp now = nowTs();
117	        jdbc.update("INSERT INTO recipe (recipe_code, version, liquor_ratio, status, created_at) "
118	                + "VALUES (?, ?, ?, ?, ?)",
119	                recipeCode, newVersion, req.liquorRatio(), RecipeStatus.DRAFT.name(), now);
120	        Long recipeId = jdbc.queryForObject(
121	                "SELECT id FROM recipe WHERE recipe_code = ? AND version = ?",
122	                Long.class, recipeCode, newVersion);
123	        insertItems(recipeId, req.items());
124	        return ServiceResult.created(recipeView(recipeCode, newVersion));
125	    }
126	
127	    // ---------------------------------------------------------------------
128	    // 打小样对色
129	    // ---------------------------------------------------------------------
130	
131	    @Transactional
132	    public ServiceResult colorCheck(ColorCheckRequest req) {
133	        Map<String, Object> payload = new LinkedHashMap<>();
134	        payload.put("sampleId", req.sampleId());
135	        payload.put("deltaE", req.deltaE());
136	        return idempotency.execute(req.requestId(), "COLOR_CHECK", payload, () -> {
137	            boolean passed = req.deltaE().compareTo(COLOR_LIMIT) <= 0;
138	            jdbc.update("INSERT INTO color_check (request_id, sample_id, delta_e, passed, created_at) "
139	                    + "VALUES (?, ?, ?, ?, ?)",
140	                    req.requestId(), req.sampleId(), req.deltaE(), passed, nowTs());
141	            Map<String, Object> body = new LinkedHashMap<>();
142	            body.put("requestId", req.requestId());
143	            body.put("sampleId", req.sampleId());
144	            body.put("deltaE", req.deltaE());
145	            body.put("limit", COLOR_LIMIT);
146	            body.put("passed", passed);
147	            body.put("decision", passed ? "放行" : "不放行");
148	            return ServiceResult.ok(body);
149	        });
150	    }
151	
152	    // ---------------------------------------------------------------------
153	    // 排缸：冻结配方版本 + 染缸唯一占用（并发唯一受理）
154	    // ---------------------------------------------------------------------
155	
156	    @Transactional
157	    public ServiceResult scheduleLot(ScheduleLotRequest req) {
158	        Map<String, Object> payload = new LinkedHashMap<>();
159	        payload.put("lotNo", req.lotNo());
160	        payload.put("vatNo", req.vatNo());
161	        payload.put("recipeCode", req.recipeCode());
162	        payload.put("recipeVersion", req.recipeVersion());
163	        payload.put("fabricWeightKg", req.fabricWeightKg());
164	        return idempotency.execute(req.requestId(), "SCHEDULE", payload, () -> {
165	            Map<String, Object> recipe = requirePublishedRecipe(req.recipeCode(), req.recipeVersion());
166	            Timestamp now = nowTs();
167	            Long lotId;
168	            try {
169	                jdbc.update("INSERT INTO lot (lot_no, vat_no, recipe_code, recipe_version, liquor_ratio, "
170	                        + "fabric_weight_kg, status, repair_count, created_at, updated_at) "
171	                        + "VALUES (?, ?, ?, ?, ?, ?, ?, 0, ?, ?)",
172	                        req.lotNo(), req.vatNo(), req.recipeCode(), req.recipeVersion(),
173	                        recipe.get("liquor_ratio"), req.fabricWeightKg(), LotStatus.CREATED.name(), now, now);
174	                lotId = jdbc.queryForObject("SELECT id FROM lot WHERE lot_no = ?", Long.class, req.lotNo());
175	            } catch (DuplicateKeyException dupLot) {
176	                throw new ApiException(HttpStatus.CONFLICT, "缸次号 " + req.lotNo() + " 已存在");
177	            }
178	            try {
179	                // 行存在即占用：主键冲突保证同一染缸同时刻只有一个执行中缸次，并发排缸唯一受理。
180	                jdbc.update("INSERT INTO vat_active (vat_no, lot_id, since) VALUES (?, ?, ?)",
181	                        req.vatNo(), lotId, now);
182	            } catch (DuplicateKeyException dupVat) {
183	                throw new ApiException(HttpStatus.CONFLICT,
184	                        "染缸 " + req.vatNo() + " 已有执行中缸次，并发排缸唯一受理");
185	            }
186	            return ServiceResult.created(lotView(req.lotNo()));
187	        });
188	    }
189	
190	    /**
191	     * 受控排缸：与普通排缸同样冻结已发布配方版本并唯一占用染缸，但缸次标记 controlled=TRUE，
192	     * 投料前必须取得效价补偿批准。
193	     */
194	    @Transactional
195	    public ServiceResult scheduleControlledLot(ScheduleControlledRequest req) {
196	        Map<String, Object> payload = new LinkedHashMap<>();
197	        payload.put("lotNo", req.lotNo());
198	        payload.put("vatNo", req.vatNo());
199	        payload.put("recipeCode", req.recipeCode());
200	        payload.put("recipeVersion", req.recipeVersion());
201	        payload.put("fabricWeightKg", req.fabricWeightKg());
202	        payload.put("controlled", true);
203	        return idempotency.execute(req.requestId(), "SCHEDULE_CONTROLLED", payload, () -> {
204	            Map<String, Object> recipe = requirePublishedRecipe(req.recipeCode(), req.recipeVersion());
205	            Timestamp now = nowTs();
206	            Long lotId;
207	            try {
208	                jdbc.update("INSERT INTO lot (lot_no, vat_no, recipe_code, recipe_version, liquor_ratio, "
209	                        + "fabric_weight_kg, controlled, status, repair_count, created_at, updated_at) "
210	                        + "VALUES (?, ?, ?, ?, ?, ?, TRUE, ?, 0, ?, ?)",
211	                        req.lotNo(), req.vatNo(), req.recipeCode(), req.recipeVersion(),
212	                        recipe.get("liquor_ratio"), req.fabricWeightKg(), LotStatus.CREATED.name(), now, now);
213	                lotId = jdbc.queryForObject("SELECT id FROM lot WHERE lot_no = ?", Long.class, req.lotNo());
214	            } catch (DuplicateKeyException dupLot) {
215	                throw new ApiException(HttpStatus.CONFLICT, "缸次号 " + req.lotNo() + " 已存在");
216	            }
217	            try {
218	                jdbc.update("INSERT INTO vat_active (vat_no, lot_id, since) VALUES (?, ?, ?)",
219	                        req.vatNo(), lotId, now);
220	            } catch (DuplicateKeyException dupVat) {
221	                throw new ApiException(HttpStatus.CONFLICT,
222	                        "染缸 " + req.vatNo() + " 已有执行中缸次，并发排缸唯一受理");
223	            }
224	            return ServiceResult.created(lotView(req.lotNo()));
225	        });
226	    }
227	
228	    // ---------------------------------------------------------------------
229	    // 并缸：须同配方（同编码同冻结版本）同浴比
230	    // ---------------------------------------------------------------------
231	
232	    @Transactional
233	    public ServiceResult mergeLots(MergeLotsRequest req) {
234	        Map<String, Object> payload = new LinkedHashMap<>();
235	        payload.put("lotNo", req.lotNo());
236	        payload.put("targetLotNo", req.targetLotNo());
237	        payload.put("expectedVersion", req.expectedVersion());
238	        return idempotency.execute(req.requestId(), "MERGE", payload, () -> {
239	            if (req.lotNo().equals(req.targetLotNo())) {
240	                throw new ApiException(HttpStatus.BAD_REQUEST, "缸次不能与自身并缸");
241	            }
242	            Map<String, Object> source = requireLot(req.lotNo());
243	            Map<String, Object> target = requireLot(req.targetLotNo());
244	            requireStatus(source, LotStatus.CREATED);
245	            requireStatus(target, LotStatus.CREATED);
246	            if (!source.get("recipe_code").equals(target.get("recipe_code"))
247	                    || ((Number) source.get("recipe_version")).intValue()
248	                        != ((Number) target.get("recipe_version")).intValue()) {
249	                throw new ApiException(HttpStatus.CONFLICT,
250	                        "不同配方拒绝并缸：" + source.get("recipe_code") + " v" + source.get("recipe_version")
251	                                + " 与 " + target.get("recipe_code") + " v" + target.get("recipe_version"));
252	            }
253	            if (((BigDecimal) source.get("liquor_ratio")).compareTo((BigDecimal) target.get("liquor_ratio")) != 0) {
254	                throw new ApiException(HttpStatus.CONFLICT, "浴比不同拒绝并缸");
255	            }
256	
257	            boolean sourceControlled = Boolean.TRUE.equals(source.get("controlled"));
258	            boolean targetControlled = Boolean.TRUE.equals(target.get("controlled"));
259	            if (sourceControlled != targetControlled) {
260	                throw new ApiException(HttpStatus.UNPROCESSABLE_ENTITY,
261	                        "受控缸次与旧非受控缸次不得并缸：" + req.lotNo() + " controlled=" + sourceControlled
262	                                + "，" + req.targetLotNo() + " controlled=" + targetControlled);
263	            }
264	
265	            Map<String, Object> sourceComp = null;
266	            Map<String, Object> targetComp = null;
267	            if (sourceControlled) {
268	                // 受控并缸：补偿批次与补偿目标必须完全相同；按缸次主键升序加锁避免反向并缸互锁。
269	                Map<String, Object> firstLot = ((Number) source.get("id")).longValue()
270	                        < ((Number) target.get("id")).longValue() ? source : target;
271	                Map<String, Object> secondLot = firstLot == source ? target : source;
272	                requireFrozenCompensation(firstLot, String.valueOf(firstLot.get("lot_no")));
273	                requireFrozenCompensation(secondLot, String.valueOf(secondLot.get("lot_no")));
274	                sourceComp = requireFrozenCompensation(source, req.lotNo());
275	                targetComp = requireFrozenCompensation(target, req.targetLotNo());
276	                if (req.expectedVersion() == null) {
277	                    throw new ApiException(HttpStatus.BAD_REQUEST,
278	                            "受控并缸须携带目标缸次补偿批准 expectedVersion");
279	                }
280	                int targetCompVersion = ((Number) targetComp.get("version")).intValue();
281	                if (req.expectedVersion() != targetCompVersion) {
282	                    throw new ApiException(HttpStatus.CONFLICT,
283	                            "补偿批准版本冲突：expectedVersion=" + req.expectedVersion()
284	                                    + "，目标缸当前版本=" + targetCompVersion);
285	                }
286	                assertSameCompensation(sourceComp, targetComp, req.lotNo(), req.targetLotNo());
287	            }
288	
289	            Timestamp now = nowTs();
290	            BigDecimal combinedWeight = ((BigDecimal) source.get("fabric_weight_kg"))
291	                    .add((BigDecimal) target.get("fabric_weight_kg"));
292	            jdbc.update("UPDATE lot SET merged_into_lot_id = ?, status = ?, updated_at = ? WHERE id = ?",
293	                    target.get("id"), LotStatus.MERGED.name(), now, source.get("id"));
294	            jdbc.update("UPDATE lot SET fabric_weight_kg = ?, updated_at = ? WHERE id = ?",
295	                    combinedWeight, now, target.get("id"));
296	            // 被并缸次释放原染缸占用，织物并入目标缸同缸生产。
297	            jdbc.update("DELETE FROM vat_active WHERE vat_no = ? AND lot_id = ?",
298	                    source.get("vat_no"), source.get("id"));
299	
300	            int targetCompVersionAfter = -1;
301	            if (sourceControlled) {
302	                // 源缸补偿批准随并缸失效（未投料）；目标缸按合并布重用同批次同系数重冻补偿，版本加 1。
303	                int sourceCompVersion = ((Number) sourceComp.get("version")).intValue();
304	                jdbc.update("UPDATE compensation SET status = ?, invalid_reason = ?, version = version + 1, "
305	                        + "updated_at = ? WHERE id = ? AND status = ? AND version = ?",
306	                        CompensationStatus.INVALID.name(),
307	                        "缸次已并入 " + req.targetLotNo() + "，未投料补偿随并缸失效",
308	                        now, sourceComp.get("id"), CompensationStatus.FROZEN.name(), sourceCompVersion);
309	                targetCompVersionAfter = refreezeCompensationForMergedWeight(
310	                        target, targetComp, combinedWeight, now);
311	            }
312	
313	            Map<String, Object> body = new LinkedHashMap<>();
314	            body.put("requestId", req.requestId());
315	            body.put("mergedLotNo", req.lotNo());
316	            body.put("targetLotNo", req.targetLotNo());
317	            body.put("combinedFabricWeightKg", combinedWeight);
318	            body.put("controlled", sourceControlled);
319	            if (sourceControlled) {
320	                body.put("compensationVersion", targetCompVersionAfter);
321	            }
322	            body.put("status", LotStatus.MERGED.name());
323	            return ServiceResult.ok(body);
324	        });
325	    }
326	
327	    /** 读取缸次的补偿批准并锁定，要求仍处于 FROZEN（已失效/已投料/未批准均拒绝受控投料前操作）。 */
328	    private Map<String, Object> requireFrozenCompensation(Map<String, Object> lot, String lotNo) {
329	        List<Map<String, Object>> rows = jdbc.queryForList(
330	                "SELECT id, status, version FROM compensation WHERE lot_id = ? FOR UPDATE", lot.get("id"));
331	        if (rows.isEmpty()) {
332	            throw new ApiException(HttpStatus.UNPROCESSABLE_ENTITY,
333	                    "受控缸次 " + lotNo + " 尚未取得效价补偿批准，拒绝操作");
334	        }
335	        Map<String, Object> comp = rows.get(0);
336	        if (!CompensationStatus.FROZEN.name().equals(comp.get("status"))) {
337	            throw new ApiException(HttpStatus.UNPROCESSABLE_ENTITY,
338	                    "受控缸次 " + lotNo + " 补偿批准状态为 " + comp.get("status") + "，须重新审批后再操作");
339	        }
340	        return comp;
341	    }
342	
343	    /** 逐染料比较两份冻结补偿：染料集合、批次号、系数版本与补偿目标克重必须完全一致。 */
344	    private void assertSameCompensation(Map<String, Object> sourceComp, Map<String, Object> targetComp,
345	                                        String sourceLotNo, String targetLotNo) {
346	        List<Map<String, Object>> sourceItems = jdbc.queryForList(
347	                "SELECT dye_code, batch_no, factor_version, compensated_target_g FROM compensation_item "
348	                        + "WHERE compensation_id = ? ORDER BY dye_code", sourceComp.get("id"));
349	        List<Map<String, Object>> targetItems = jdbc.queryForList(
350	                "SELECT dye_code, batch_no, factor_version, compensated_target_g FROM compensation_item "
351	                        + "WHERE compensation_id = ? ORDER BY dye_code", targetComp.get("id"));
352	        if (sourceItems.size() != targetItems.size()) {
353	            throw new ApiException(HttpStatus.UNPROCESSABLE_ENTITY,
354	                    "受控并缸拒绝：两缸补偿染料集合不同");
355	        }
356	        for (int i = 0; i < sourceItems.size(); i++) {
357	            Map<String, Object> a = sourceItems.get(i);
358	            Map<String, Object> b = targetItems.get(i);
359	            boolean same = a.get("dye_code").equals(b.get("dye_code"))
360	                    && a.get("batch_no").equals(b.get("batch_no"))
361	                    && ((Number) a.get("factor_version")).intValue()
362	                        == ((Number) b.get("factor_version")).intValue()
363	                    && ((BigDecimal) a.get("compensated_target_g"))
364	                            .compareTo((BigDecimal) b.get("compensated_target_g")) == 0;
365	            if (!same) {
366	                throw new ApiException(HttpStatus.UNPROCESSABLE_ENTITY,
367	                        "受控并缸拒绝：染料 " + a.get("dye_code") + " 补偿不一致——"
368	                                + sourceLotNo + " 批次 " + a.get("batch_no") + " v" + a.get("factor_version")
369	                                + " 目标 " + a.get("compensated_target_g") + "g；"
370	                                + targetLotNo + " 批次 " + b.get("batch_no") + " v" + b.get("factor_version")
371	                                + " 目标 " + b.get("compensated_target_g") + "g");
372	            }
373	        }
374	    }
375	
376	    /**
377	     * 并缸后按合并布重、沿用同批次同系数重冻目标缸补偿目标，返回复查后新版本号。
378	     * 先锁定并校验各批次（版本仍有效、未到截止、余量足以支撑合并目标），全部通过后才改写冻结项，
379	     * 任一批次不满足则整单回滚，源缸与目标缸都保持原状态。
380	     */
381	    private int refreezeCompensationForMergedWeight(Map<String, Object> targetLot,
382	                                                    Map<String, Object> targetComp,
383	                                                    BigDecimal combinedWeight, Timestamp now) {
384	        BigDecimal ratio = (BigDecimal) targetLot.get("liquor_ratio");
385	        List<Map<String, Object>> items = jdbc.queryForList(
386	                "SELECT dye_code, batch_no, factor_version, potency_factor FROM compensation_item "
387	                        + "WHERE compensation_id = ? ORDER BY dye_code", targetComp.get("id"));
388	
389	        List<Map<String, Object>> reFrozen = new ArrayList<>();
390	        for (Map<String, Object> item : items) {
391	            String batchNo = (String) item.get("batch_no");
392	            int factorVersion = ((Number) item.get("factor_version")).intValue();
393	            List<Map<String, Object>> batchRows = jdbc.queryForList(
394	                    "SELECT dye_code, available_g, expire_at, active FROM dye_batch "
395	                            + "WHERE batch_no = ? AND factor_version = ? FOR UPDATE",
396	                    batchNo, factorVersion);
397	            if (batchRows.isEmpty() || !Boolean.TRUE.equals(batchRows.get(0).get("active"))) {
398	                throw new ApiException(HttpStatus.UNPROCESSABLE_ENTITY,
399	                        "受控并缸拒绝：批次 " + batchNo + " 系数版本 v" + factorVersion + " 已失效，请重新审批");
400	            }
401	            Map<String, Object> batch = batchRows.get(0);
402	            Timestamp expireAt = (Timestamp) batch.get("expire_at");
403	            if (!now.before(expireAt)) {
404	                throw new ApiException(HttpStatus.UNPROCESSABLE_ENTITY,
405	                        "受控并缸拒绝：批次 " + batchNo + " 已到/超过有效截止（恰在截止即失效）");
406	            }
407	            BigDecimal dosage = jdbc.queryForObject(
408	                    "SELECT ri.dosage_gpl FROM recipe_item ri JOIN recipe r ON r.id = ri.recipe_id "
409	                            + "WHERE r.recipe_code = ? AND r.version = ? AND ri.dye_code = ?",
410	                    BigDecimal.class, targetLot.get("recipe_code"),
411	                    targetLot.get("recipe_version"), item.get("dye_code"));
412	            BigDecimal factor = (BigDecimal) item.get("potency_factor");
413	            BigDecimal baseTarget = dosage.multiply(ratio).multiply(combinedWeight)
414	                    .setScale(4, RoundingMode.HALF_UP);
415	            BigDecimal compensated = baseTarget.divide(factor, 3, RoundingMode.HALF_UP);
416	            BigDecimal available = (BigDecimal) batch.get("available_g");
417	            if (available.compareTo(compensated) < 0) {
418	                throw new ApiException(HttpStatus.UNPROCESSABLE_ENTITY,
419	                        "受控并缸拒绝：批次 " + batchNo + " 余量 " + available + "g 不足合并后补偿目标 "
420	                                + compensated + "g，整单回滚");
421	            }
422	            Map<String, Object> row = new LinkedHashMap<>();
423	            row.put("dyeCode", item.get("dye_code"));
424	            row.put("batchNo", batchNo);
425	            row.put("factorVersion", factorVersion);
426	            row.put("potencyFactor", factor);
427	            row.put("baseTargetG", baseTarget);
428	            row.put("compensatedTargetG", compensated);
429	            reFrozen.add(row);
430	        }
431	
432	        jdbc.update("DELETE FROM compensation_item WHERE compensation_id = ?", targetComp.get("id"));
433	        for (Map<String, Object> row : reFrozen) {
434	            jdbc.update("INSERT INTO compensation_item (compensation_id, dye_code, batch_no, factor_version, "
435	                    + "potency_factor, base_target_g, compensated_target_g) VALUES (?, ?, ?, ?, ?, ?, ?)",
436	                    targetComp.get("id"), row.get("dyeCode"), row.get("batchNo"), row.get("factorVersion"),
437	                    row.get("potencyFactor"), row.get("baseTargetG"), row.get("compensatedTargetG"));
438	        }
439	        int currentVersion = ((Number) targetComp.get("version")).intValue();
440	        int nextVersion = currentVersion + 1;
441	        jdbc.update("UPDATE compensation SET version = ?, updated_at = ? WHERE id = ? AND version = ?",
442	                nextVersion, now, targetComp.get("id"), currentVersion);
443	        return nextVersion;
444	    }
