450	    @Transactional
451	    public ServiceResult feed(FeedRequest req) {
452	        Map<String, Object> payload = new LinkedHashMap<>();
453	        payload.put("lotNo", req.lotNo());
454	        payload.put("expectedVersion", req.expectedVersion());
455	        List<Map<String, Object>> weighingPayload = new ArrayList<>();
456	        for (WeighingInput w : req.weighings()) {
457	            Map<String, Object> entry = new LinkedHashMap<>();
458	            entry.put("dyeCode", w.dyeCode());
459	            entry.put("actualG", w.actualG());
460	            weighingPayload.add(entry);
461	        }
462	        weighingPayload.sort((a, b) -> String.valueOf(a.get("dyeCode")).compareTo(String.valueOf(b.get("dyeCode"))));
463	        payload.put("weighings", weighingPayload);
464	
465	        return idempotency.execute(req.requestId(), "FEED", payload, () -> {
466	            Map<String, Object> lot = requireLot(req.lotNo());
467	            requireStatus(lot, LotStatus.CREATED);
468	            if (Boolean.TRUE.equals(lot.get("controlled"))) {
469	                return feedControlled(req, lot);
470	            }
471	            if (req.expectedVersion() != null) {
472	                throw new ApiException(HttpStatus.BAD_REQUEST,
473	                        "旧非受控缸次投料不接受 expectedVersion，请使用原投料语义");
474	            }
475	            return feedLegacy(req, lot);
476	        });
477	    }
