479	    /**
480	     * 受控投料：同时验证补偿版本（FROZEN + expectedVersion）、称量偏差（按补偿目标）与批次有效期，
481	     * 原子扣减各染料批次余量并写称量链；第二种不足时第一种也不扣。两缸争同批余量由条件更新防超耗。
482	     */
483	    private ServiceResult feedControlled(FeedRequest req, Map<String, Object> lot) {
484	        if (req.expectedVersion() == null) {
485	            throw new ApiException(HttpStatus.BAD_REQUEST,
486	                    "受控缸次投料须携带补偿批准 expectedVersion");
487	        }
488	        Timestamp now = nowTs();
489	
490	        // 锁定补偿批准：FROZEN 且版本匹配；修订/失效/已投料在此拦截。
491	        List<Map<String, Object>> compRows = jdbc.queryForList(
492	                "SELECT id, status, version FROM compensation WHERE lot_id = ? FOR UPDATE", lot.get("id"));
493	        if (compRows.isEmpty()) {
494	            throw new ApiException(HttpStatus.UNPROCESSABLE_ENTITY,
495	                    "受控缸次 " + req.lotNo() + " 尚未取得效价补偿批准，拒绝投料");
496	        }
497	        Map<String, Object> comp = compRows.get(0);
498	        int compVersion = ((Number) comp.get("version")).intValue();
499	        if (!CompensationStatus.FROZEN.name().equals(comp.get("status"))) {
500	            throw new ApiException(HttpStatus.UNPROCESSABLE_ENTITY,
501	                    "受控缸次 " + req.lotNo() + " 补偿批准状态为 " + comp.get("status")
502	                            + "（系数修订或已失效），须重新审批后投料");
503	        }
504	        if (req.expectedVersion() != compVersion) {
505	            throw new ApiException(HttpStatus.CONFLICT,
506	                    "补偿批准版本冲突：expectedVersion=" + req.expectedVersion() + "，当前版本=" + compVersion);
507	        }
508	
509	        List<Map<String, Object>> frozenItems = jdbc.queryForList(
510	                "SELECT dye_code, batch_no, factor_version, potency_factor, base_target_g, compensated_target_g "
511	                        + "FROM compensation_item WHERE compensation_id = ? ORDER BY dye_code",
512	                comp.get("id"));
513	
514	        Map<String, BigDecimal> actualByDye = new LinkedHashMap<>();
515	        for (WeighingInput w : req.weighings()) {
516	            if (actualByDye.put(w.dyeCode(), w.actualG()) != null) {
517	                throw new ApiException(HttpStatus.BAD_REQUEST, "染料 " + w.dyeCode() + " 称量记录重复");
518	            }
519	        }
520	        Set<String> required = new LinkedHashSet<>();
521	        List<Map<String, Object>> computed = new ArrayList<>();
522	        for (Map<String, Object> fi : frozenItems) {
523	            String dyeCode = (String) fi.get("dye_code");
524	            required.add(dyeCode);
525	            BigDecimal actual = actualByDye.get(dyeCode);
526	            if (actual == null) {
527	                throw new ApiException(HttpStatus.BAD_REQUEST,
528	                        "缺少染料 " + dyeCode + " 的实际称量，拒绝投料");
529	            }
530	            // 锁定具体批次系数版本：修订后 active=FALSE 或缺失即拒绝。
531	            List<Map<String, Object>> batchRows = jdbc.queryForList(
532	                    "SELECT dye_code, potency_factor, available_g, expire_at, active "
533	                            + "FROM dye_batch WHERE batch_no = ? AND factor_version = ? FOR UPDATE",
534	                    fi.get("batch_no"), fi.get("factor_version"));
535	            if (batchRows.isEmpty()) {
536	                throw new ApiException(HttpStatus.NOT_FOUND,
537	                        "批次 " + fi.get("batch_no") + " 系数版本 v" + fi.get("factor_version") + " 不存在");
538	            }
539	            Map<String, Object> batch = batchRows.get(0);
540	            if (!dyeCode.equals(batch.get("dye_code"))) {
541	                throw new ApiException(HttpStatus.UNPROCESSABLE_ENTITY,
542	                        "染料代码错配：批次 " + fi.get("batch_no") + " 属于 " + batch.get("dye_code")
543	                                + "，不能用于 " + dyeCode + "，整单拒绝");
544	            }
545	            if (!Boolean.TRUE.equals(batch.get("active"))) {
546	                throw new ApiException(HttpStatus.UNPROCESSABLE_ENTITY,
547	                        "批次 " + fi.get("batch_no") + " 系数版本 v" + fi.get("factor_version")
548	                                + " 已被修订失效，未投料批准不得投料（须重新审批）");
549	            }
550	            Timestamp expireAt = (Timestamp) batch.get("expire_at");
551	            if (!now.before(expireAt)) {
552	                throw new ApiException(HttpStatus.UNPROCESSABLE_ENTITY,
553	                        "批次 " + fi.get("batch_no") + " 已到/超过有效截止 " + expireAt.toInstant()
554	                                + "（恰在截止即失效），整单拒绝投料");
555	            }
556	            BigDecimal factor = (BigDecimal) fi.get("potency_factor");
557	            if (factor.signum() <= 0) {
558	                throw new ApiException(HttpStatus.UNPROCESSABLE_ENTITY,
559	                        "批次 " + fi.get("batch_no") + " 冻结系数非正，整单拒绝投料");
560	            }
561	            BigDecimal target = (BigDecimal) fi.get("compensated_target_g");
562	            BigDecimal deviation = actual.subtract(target)
563	                    .multiply(BigDecimal.valueOf(100))
564	                    .divide(target, DEVIATION_SCALE, RoundingMode.HALF_UP);
565	            if (deviation.abs().compareTo(WEIGH_LIMIT_PCT) > 0) {
566	                throw new ApiException(HttpStatus.UNPROCESSABLE_ENTITY,
567	                        "染料 " + dyeCode + " 按补偿目标 " + target + "g 的称量偏差 " + deviation
568	                                + "% 超过 ±0.5%（恰 0.5% 合法），整单拒绝投料且不扣批次余量");
569	            }
570	            Map<String, Object> row = new LinkedHashMap<>();
571	            row.put("dyeCode", dyeCode);
572	            row.put("batchNo", fi.get("batch_no"));
573	            row.put("factorVersion", fi.get("factor_version"));
574	            row.put("potencyFactor", factor);
575	            row.put("baseTargetG", fi.get("base_target_g"));
576	            row.put("targetG", target);
577	            row.put("actualG", actual);
578	            row.put("deviationPct", deviation);
579	            row.put("availableG", batch.get("available_g"));
580	            computed.add(row);
581	        }
582	        if (!actualByDye.keySet().equals(required)) {
583	            Set<String> extra = new LinkedHashSet<>(actualByDye.keySet());
584	            extra.removeAll(required);
585	            throw new ApiException(HttpStatus.BAD_REQUEST, "存在补偿清单外染料称量：" + extra + "，拒绝投料");
586	        }
587	
588	        // 余量预检：任一批次不足整单回滚，杜绝部分扣减。
589	        for (Map<String, Object> row : computed) {
590	            BigDecimal available = (BigDecimal) row.get("availableG");
591	            BigDecimal actual = (BigDecimal) row.get("actualG");
592	            if (available.compareTo(actual) < 0) {
593	                throw new ApiException(HttpStatus.CONFLICT,
594	                        "批次 " + row.get("batchNo") + " 余量 " + available + "g 不足实际称量 " + actual
595	                                + "g，整单拒绝投料且不扣任何批次余量");
596	            }
597	        }
598	
599	        jdbc.update("INSERT INTO feeding (request_id, lot_id, fed_at) VALUES (?, ?, ?)",
600	                req.requestId(), lot.get("id"), now);
601	        Long feedingId = jdbc.queryForObject(
602	                "SELECT id FROM feeding WHERE request_id = ?", Long.class, req.requestId());
603	        for (Map<String, Object> row : computed) {
604	            jdbc.update("INSERT INTO weighing (feeding_id, dye_code, target_g, actual_g, deviation_pct, "
605	                    + "batch_no, factor_version, potency_factor, base_target_g) "
606	                    + "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)",
607	                    feedingId, row.get("dyeCode"), row.get("targetG"), row.get("actualG"),
608	                    row.get("deviationPct"), row.get("batchNo"), row.get("factorVersion"),
609	                    row.get("potencyFactor"), row.get("baseTargetG"));
610	            int deducted = jdbc.update(
611	                    "UPDATE dye_batch SET available_g = available_g - ? WHERE batch_no = ? AND factor_version = ? "
612	                            + "AND available_g >= ?",
613	                    row.get("actualG"), row.get("batchNo"), row.get("factorVersion"), row.get("actualG"));
614	            if (deducted != 1) {
615	                // 并发扣减防护：两缸争同批余量时败方整单回滚，不超耗。
616	                throw new ApiException(HttpStatus.CONFLICT,
617	                        "批次 " + row.get("batchNo") + " 并发余量扣减失败，整单回滚不超耗");
618	            }
619	        }
620	        int fedCompVersion = compVersion + 1;
621	        int casComp = jdbc.update(
622	                "UPDATE compensation SET status = ?, invalid_reason = NULL, version = ?, updated_at = ? "
623	                        + "WHERE id = ? AND status = ? AND version = ?",
624	                CompensationStatus.FED.name(), fedCompVersion, now,
625	                comp.get("id"), CompensationStatus.FROZEN.name(), compVersion);
626	        if (casComp != 1) {
627	            throw new ApiException(HttpStatus.CONFLICT,
628	                    "补偿批准 " + req.lotNo() + " 状态在投料并发中变化，整单回滚");
629	        }
630	        jdbc.update("UPDATE lot SET status = ?, updated_at = ? WHERE id = ?",
631	                LotStatus.FED.name(), now, lot.get("id"));
632	
633	        Map<String, Object> body = new LinkedHashMap<>();
634	        body.put("requestId", req.requestId());
635	        body.put("lotNo", req.lotNo());
636	        body.put("controlled", true);
637	        body.put("liquorRatio", lot.get("liquor_ratio"));
638	        body.put("fabricWeightKg", lot.get("fabric_weight_kg"));
639	        List<Map<String, Object>> weighingView = new ArrayList<>();
640	        for (Map<String, Object> row : computed) {
641	            Map<String, Object> w = new LinkedHashMap<>();
642	            w.put("dyeCode", row.get("dyeCode"));
643	            w.put("batchNo", row.get("batchNo"));
644	            w.put("factorVersion", row.get("factorVersion"));
645	            w.put("potencyFactor", row.get("potencyFactor"));
646	            w.put("baseTargetG", row.get("baseTargetG"));
647	            w.put("targetG", row.get("targetG"));
648	            w.put("actualG", row.get("actualG"));
649	            w.put("deviationPct", row.get("deviationPct"));
650	            weighingView.add(w);
651	        }
652	        body.put("weighings", weighingView);
653	        body.put("compensationVersion", fedCompVersion);
654	        body.put("status", LotStatus.FED.name());
655	        body.put("fedAt", now.toInstant().toString());
656	        return ServiceResult.ok(body);
657	    }
