659	    /** 旧非受控缸次投料语义：按放大配方目标校验偏差并扣染化料总库存，不涉及批次/补偿。 */
660	    private ServiceResult feedLegacy(FeedRequest req, Map<String, Object> lot) {
661	        Long versionRecipeId = recipeId((String) lot.get("recipe_code"),
662	                ((Number) lot.get("recipe_version")).intValue());
663	        List<Map<String, Object>> items = recipeItems(versionRecipeId);
664	        BigDecimal ratio = (BigDecimal) lot.get("liquor_ratio");
665	        BigDecimal fabricKg = (BigDecimal) lot.get("fabric_weight_kg");
666	
667	        Map<String, BigDecimal> actualByDye = new LinkedHashMap<>();
668	        for (WeighingInput w : req.weighings()) {
669	            if (actualByDye.put(w.dyeCode(), w.actualG()) != null) {
670	                throw new ApiException(HttpStatus.BAD_REQUEST,
671	                        "染化料 " + w.dyeCode() + " 称量记录重复");
672	            }
673	        }
674	        Set<String> required = new LinkedHashSet<>();
675	        List<Map<String, Object>> computed = new ArrayList<>();
676	        for (Map<String, Object> item : items) {
677	            String dyeCode = (String) item.get("dye_code");
678	            BigDecimal dosage = (BigDecimal) item.get("dosage_gpl");
679	            required.add(dyeCode);
680	            BigDecimal target = dosage.multiply(ratio).multiply(fabricKg).setScale(4, RoundingMode.HALF_UP);
681	            BigDecimal actual = actualByDye.get(dyeCode);
682	            if (actual == null) {
683	                throw new ApiException(HttpStatus.BAD_REQUEST,
684	                        "缺少染化料 " + dyeCode + " 的实际称量，拒绝投料");
685	            }
686	            BigDecimal deviation = actual.subtract(target)
687	                    .multiply(BigDecimal.valueOf(100))
688	                    .divide(target, DEVIATION_SCALE, RoundingMode.HALF_UP);
689	            if (deviation.abs().compareTo(WEIGH_LIMIT_PCT) > 0) {
690	                throw new ApiException(HttpStatus.UNPROCESSABLE_ENTITY,
691	                        "染化料 " + dyeCode + " 称量偏差 " + deviation + "% 超过 ±0.5%（恰 0.5% 合法），整单拒绝投料且不扣库存");
692	            }
693	            Map<String, Object> row = new LinkedHashMap<>();
694	            row.put("dyeCode", dyeCode);
695	            row.put("targetG", target);
696	            row.put("actualG", actual);
697	            row.put("deviationPct", deviation);
698	            computed.add(row);
699	        }
700	        if (!actualByDye.keySet().equals(required)) {
701	            Set<String> extra = new LinkedHashSet<>(actualByDye.keySet());
702	            extra.removeAll(required);
703	            throw new ApiException(HttpStatus.BAD_REQUEST,
704	                    "存在配方外染化料称量：" + extra + "，拒绝投料");
705	        }
706	
707	        // 库存预检：任一染化料不足整单回滚，杜绝部分扣减。
708	        for (Map<String, Object> row : computed) {
709	            BigDecimal stock = jdbc.queryForObject("SELECT stock_g FROM dye WHERE code = ?",
710	                    BigDecimal.class, row.get("dyeCode"));
711	            if (stock == null) {
712	                throw new ApiException(HttpStatus.BAD_REQUEST,
713	                        "染化料 " + row.get("dyeCode") + " 不存在，拒绝投料");
714	            }
715	            if (stock.compareTo((BigDecimal) row.get("actualG")) < 0) {
716	                throw new ApiException(HttpStatus.CONFLICT,
717	                        "染化料 " + row.get("dyeCode") + " 库存不足，拒绝投料且不扣库存");
718	            }
719	        }
720	
721	        Timestamp now = nowTs();
722	        jdbc.update("INSERT INTO feeding (request_id, lot_id, fed_at) VALUES (?, ?, ?)",
723	                req.requestId(), lot.get("id"), now);
724	        Long feedingId = jdbc.queryForObject(
725	                "SELECT id FROM feeding WHERE request_id = ?", Long.class, req.requestId());
726	        for (Map<String, Object> row : computed) {
727	            jdbc.update("INSERT INTO weighing (feeding_id, dye_code, target_g, actual_g, deviation_pct) "
728	                    + "VALUES (?, ?, ?, ?, ?)",
729	                    feedingId, row.get("dyeCode"), row.get("targetG"), row.get("actualG"),
730	                    row.get("deviationPct"));
731	            int deducted = jdbc.update("UPDATE dye SET stock_g = stock_g - ? WHERE code = ? AND stock_g >= ?",
732	                    row.get("actualG"), row.get("dyeCode"), row.get("actualG"));
733	            if (deducted != 1) {
734	                // 并发扣减防护：与预检构成双保险，失败随事务整体回滚。
735	                throw new ApiException(HttpStatus.CONFLICT,
736	                        "染化料 " + row.get("dyeCode") + " 并发扣减失败，整单回滚");
737	            }
738	        }
739	        jdbc.update("UPDATE lot SET status = ?, updated_at = ? WHERE id = ?",
740	                LotStatus.FED.name(), now, lot.get("id"));
741	
742	        Map<String, Object> body = new LinkedHashMap<>();
743	        body.put("requestId", req.requestId());
744	        body.put("lotNo", req.lotNo());
745	        body.put("controlled", false);
746	        body.put("liquorRatio", ratio);
747	        body.put("fabricWeightKg", fabricKg);
748	        body.put("weighings", computed);
749	        body.put("status", LotStatus.FED.name());
750	        body.put("fedAt", now.toInstant().toString());
751	        return ServiceResult.ok(body);
752	    }
