755	    // 出缸判定：同配方缸差 > 0.5 回修一次，回修后仍超差降级
756	    // ---------------------------------------------------------------------
757	
758	    @Transactional
759	    public ServiceResult judge(JudgeRequest req) {
760	        Map<String, Object> payload = new LinkedHashMap<>();
761	        payload.put("lotNo", req.lotNo());
762	        payload.put("deltaE", req.deltaE());
763	        payload.put("referenceLotNo", req.referenceLotNo() == null ? "" : req.referenceLotNo());
764	        return idempotency.execute(req.requestId(), "JUDGE", payload, () -> {
765	            Map<String, Object> lot = requireLot(req.lotNo());
766	            String status = (String) lot.get("status");
767	            int round;
768	            if (LotStatus.FED.name().equals(status)) {
769	                round = 0;
770	            } else if (LotStatus.REPAIRING.name().equals(status)) {
771	                round = ((Number) lot.get("repair_count")).intValue();
772	            } else {
773	                throw new ApiException(HttpStatus.CONFLICT,
774	                        "缸次 " + req.lotNo() + " 当前状态 " + status + "，不允许出缸判定（须已投料或回修中）");
775	            }
776	
777	            Map<String, Object> reference = null;
778	            if (req.referenceLotNo() != null && !req.referenceLotNo().isBlank()) {
779	                reference = requireLot(req.referenceLotNo());
780	                if (!reference.get("recipe_code").equals(lot.get("recipe_code"))
781	                        || ((Number) reference.get("recipe_version")).intValue()
782	                        != ((Number) lot.get("recipe_version")).intValue()) {
783	                    throw new ApiException(HttpStatus.BAD_REQUEST, "对比缸必须同配方同冻结版本");
784	                }
785	            } else {
786	                reference = latestJudgedSibling(lot);
787	            }
788	
789	            BigDecimal refDelta = null;
790	            BigDecimal diff = null;
791	            if (reference != null) {
792	                refDelta = latestDelta((Long) reference.get("id"));
793	                if (refDelta == null) {
794	                    throw new ApiException(HttpStatus.BAD_REQUEST,
795	                            "对比缸 " + reference.get("lot_no") + " 尚无出缸测色记录，无法计算缸差");
796	                }
797	                diff = req.deltaE().subtract(refDelta).abs().setScale(4, RoundingMode.HALF_UP);
798	            }
799	
800	            Verdict verdict;
801	            LotStatus nextStatus;
802	            boolean over = diff != null && diff.compareTo(LOT_DIFF_LIMIT) > 0;
803	            if (!over) {
804	                verdict = Verdict.PASS;
805	                nextStatus = LotStatus.PASSED;
806	            } else if (round == 0) {
807	                verdict = Verdict.REPAIR;
808	                nextStatus = LotStatus.REPAIRING;
809	            } else {
810	                verdict = Verdict.DOWNGRADE;
811	                nextStatus = LotStatus.DOWNGRADED;
812	            }
813	
814	            Timestamp now = nowTs();
815	            jdbc.update("INSERT INTO lot_judgment (request_id, lot_id, round, delta_e, reference_lot_id, "
816	                    + "reference_delta_e, diff, verdict, judged_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)",
817	                    req.requestId(), lot.get("id"), round, req.deltaE(),
818	                    reference == null ? null : reference.get("id"), refDelta, diff, verdict.name(), now);
819	            int newRepairCount = ((Number) lot.get("repair_count")).intValue()
820	                    + (verdict == Verdict.REPAIR ? 1 : 0);
821	            jdbc.update("UPDATE lot SET status = ?, repair_count = ?, updated_at = ? WHERE id = ?",
822	                    nextStatus.name(), newRepairCount, now, lot.get("id"));
823	
824	            Map<String, Object> body = new LinkedHashMap<>();
825	            body.put("requestId", req.requestId());
826	            body.put("lotNo", req.lotNo());
827	            body.put("round", round);
828	            body.put("deltaE", req.deltaE());
829	            body.put("referenceLotNo", reference == null ? null : reference.get("lot_no"));
830	            body.put("referenceDeltaE", refDelta);
831	            body.put("diff", diff);
832	            body.put("limit", LOT_DIFF_LIMIT);
833	            body.put("verdict", verdict.name());
834	            body.put("status", nextStatus.name());
835	            body.put("repairCount", newRepairCount);
836	            body.put("note", verdictNote(verdict));
837	            return ServiceResult.ok(body);
838	        });
839	    }
