906	    /**
907	     * 复算配方版本、称量链与缸差台账：重算目标克重/偏差/缸差并与库存与台账逐笔比对。
908	     */
909	    @Transactional(readOnly = true)
910	    public ServiceResult recalculate(String recipeCode) {
911	        List<Map<String, Object>> versions = new ArrayList<>();
912	        List<Map<String, Object>> versionRows = jdbc.queryForList(
913	                "SELECT id, version, liquor_ratio, status FROM recipe WHERE recipe_code = ? ORDER BY version",
914	                recipeCode);
915	        for (Map<String, Object> v : versionRows) {
916	            Map<String, Object> view = new LinkedHashMap<>(v);
917	            view.put("items", recipeItems(((Number) v.get("id")).longValue()));
918	            versions.add(view);
919	        }
920	        if (versions.isEmpty()) {
921	            throw new ApiException(HttpStatus.NOT_FOUND, "配方 " + recipeCode + " 不存在");
922	        }
923	
924	        List<Map<String, Object>> weighingMismatches = new ArrayList<>();
925	        int weighingChecked = 0;
926	        List<Map<String, Object>> lotRows = jdbc.queryForList(
927	                "SELECT * FROM lot WHERE recipe_code = ? ORDER BY id", recipeCode);
928	        for (Map<String, Object> lot : lotRows) {
929	            BigDecimal ratio = (BigDecimal) lot.get("liquor_ratio");
930	            BigDecimal fabric = (BigDecimal) lot.get("fabric_weight_kg");
931	            boolean controlledLot = Boolean.TRUE.equals(lot.get("controlled"));
932	            List<Map<String, Object>> stored = jdbc.queryForList(
933	                    "SELECT dye_code, target_g, actual_g, deviation_pct FROM weighing w "
934	                            + "JOIN feeding f ON f.id = w.feeding_id WHERE f.lot_id = ? ORDER BY w.id",
935	                    lot.get("id"));
936	            for (Map<String, Object> w : stored) {
937	                BigDecimal target;
938	                if (controlledLot) {
939	                    // 受控缸称量目标冻结于补偿批准（原目标/系数，三位小数），已投料历史不随批次修订改变。
940	                    target = jdbc.queryForObject(
941	                            "SELECT ci.compensated_target_g FROM compensation_item ci "
942	                                    + "JOIN compensation c ON c.id = ci.compensation_id "
943	                                    + "WHERE c.lot_id = ? AND ci.dye_code = ?",
944	                            BigDecimal.class, lot.get("id"), w.get("dye_code"));
945	                } else {
946	                    BigDecimal dosage = jdbc.queryForObject(
947	                            "SELECT dosage_gpl FROM recipe_item ri JOIN recipe r ON r.id = ri.recipe_id "
948	                                    + "WHERE r.recipe_code = ? AND r.version = ? AND ri.dye_code = ?",
949	                            BigDecimal.class, recipeCode, lot.get("recipe_version"), w.get("dye_code"));
950	                    target = dosage.multiply(ratio).multiply(fabric).setScale(4, RoundingMode.HALF_UP);
951	                }
952	                BigDecimal deviation = ((BigDecimal) w.get("actual_g")).subtract(target)
953	                        .multiply(BigDecimal.valueOf(100))
954	                        .divide(target, DEVIATION_SCALE, RoundingMode.HALF_UP);
955	                weighingChecked++;
956	                if (target.compareTo((BigDecimal) w.get("target_g")) != 0
957	                        || deviation.compareTo((BigDecimal) w.get("deviation_pct")) != 0) {
958	                    Map<String, Object> mismatch = new LinkedHashMap<>();
959	                    mismatch.put("lotNo", lot.get("lot_no"));
960	                    mismatch.put("dyeCode", w.get("dye_code"));
961	                    mismatch.put("controlled", controlledLot);
962	                    mismatch.put("storedTargetG", w.get("target_g"));
963	                    mismatch.put("recomputedTargetG", target);
964	                    mismatch.put("storedDeviationPct", w.get("deviation_pct"));
965	                    mismatch.put("recomputedDeviationPct", deviation);
966	                    weighingMismatches.add(mismatch);
967	                }
968	            }
969	        }
970	
971	        List<Map<String, Object>> judgmentRows = jdbc.queryForList(
972	                "SELECT j.*, l.lot_no AS lot_no FROM lot_judgment j JOIN lot l ON l.id = j.lot_id "
973	                        + "WHERE l.recipe_code = ? ORDER BY j.id", recipeCode);
974	        List<Map<String, Object>> judgmentMismatches = new ArrayList<>();
975	        for (Map<String, Object> j : judgmentRows) {
976	            BigDecimal storedDiff = (BigDecimal) j.get("diff");
977	            Verdict storedVerdict = Verdict.valueOf((String) j.get("verdict"));
978	            BigDecimal recomputedDiff = null;
979	            if (j.get("reference_lot_id") != null) {
980	                Map<String, Object> refRow = jdbc.queryForMap(
981	                        "SELECT delta_e FROM lot_judgment WHERE lot_id = ? ORDER BY id DESC LIMIT 1",
982	                        j.get("reference_lot_id"));
983	                recomputedDiff = ((BigDecimal) j.get("delta_e")).subtract((BigDecimal) refRow.get("delta_e"))
984	                        .abs().setScale(4, RoundingMode.HALF_UP);
985	            }
986	            int round = ((Number) j.get("round")).intValue();
987	            boolean over = recomputedDiff != null && recomputedDiff.compareTo(LOT_DIFF_LIMIT) > 0;
988	            Verdict expectedVerdict;
989	            if (!over) {
990	                expectedVerdict = Verdict.PASS;
991	            } else if (round == 0) {
992	                expectedVerdict = Verdict.REPAIR;
993	            } else {
994	                expectedVerdict = Verdict.DOWNGRADE;
995	            }
996	            boolean diffOk = storedDiff == null ? recomputedDiff == null
997	                    : recomputedDiff != null && storedDiff.compareTo(recomputedDiff) == 0;
998	            if (!diffOk || storedVerdict != expectedVerdict) {
999	                Map<String, Object> mismatch = new LinkedHashMap<>();
1000	                mismatch.put("lotNo", j.get("lot_no"));
1001	                mismatch.put("storedDiff", storedDiff);
1002	                mismatch.put("recomputedDiff", recomputedDiff);
1003	                mismatch.put("storedVerdict", storedVerdict.name());
1004	                mismatch.put("expectedVerdict", expectedVerdict.name());
1005	                judgmentMismatches.add(mismatch);
1006	            }
1007	        }
1008	
1009	        Map<String, Object> report = new LinkedHashMap<>();
1010	        report.put("recipeCode", recipeCode);
1011	        report.put("versions", versions);
1012	        report.put("weighingChecked", weighingChecked);
1013	        report.put("weighingMismatches", weighingMismatches);
1014	        report.put("judgmentChecked", judgmentRows.size());
1015	        report.put("judgmentMismatches", judgmentMismatches);
1016	        report.put("consistent", weighingMismatches.isEmpty() && judgmentMismatches.isEmpty());
1017	        return ServiceResult.ok(report);
1018	    }
